"""
PAPER tracker for the user's exit rule: take profit +6 / stop loss -11 option
premium points (user, 9 Oct 2026), time stop 10 min (RULES.md §6).

OBSERVATION ONLY. Nothing here talks to a broker: it receives prices that the
read-only scanner already fetched and records what WOULD have happened. There
is no order, position or account logic anywhere in this module.

Entry event (exploratory, NOT a CE/PE signal; D1-D8 are undecided):
  the SENSEX index CROSSES a refresh-table trigger of a row whose status is OK
  (CE: from below to >= breakoutAbove; PE: from above to <= breakdownBelow),
  outside the no-trade windows. Each (side, trigger) fires once per session,
  for every configured strike of that side (one paper trade per strike).
FILTERED variant (user, 16 Oct 2026, from the 12-16 Oct paper analysis; observation only, not a rule):
  enters like FIRST_TOUCH but only when, at the crossing,
    1. the side agrees with the day trend: listed-futures LTP above its day open for CE, below for PE
       (futures LTP and open from the latest scan);
    2. the level behind the trigger has fewer than `filter_min_touches` touches and the session range so
       far (1-min index bars) is at least `filter_min_range_pts`;
    3. the strike is not in the money by more than `filter_max_itm_pts` (checked per strike);
    4. the index is less than `filter_max_overshoot_pts` beyond the trigger.
  Missing data fails a filter (no entry). Every skipped crossing logs `paper_skip` with the reasons.
Fill model: entry at the option's ASK at the first poll after the crossing;
  exits evaluated on the BID (what a sell would get). Both sides of the spread
  are therefore already inside the result. Polling is discrete (every few
  seconds), so a move that hits both levels between two polls cannot be
  ordered; such a case is impossible to see and is not invented.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from datetime import datetime, timezone


@dataclass
class PaperConfig:
    take_profit_pts: float = 6.0       # user rule, option premium points
    stop_loss_pts: float = 11.0        # user rule, option premium points
    time_stop_s: float = 600.0         # RULES.md §6 time stop 10 min
    max_open: int = 40
    lot_size: int | None = None        # set to report rupees; never guessed
    cost_per_trade_rs: float | None = None   # brokerage + statutory per round trip, if you supply it
    variant: str = "FIRST_TOUCH"       # FIRST_TOUCH: enter at the crossing poll
                                       # CONFIRMED_CLOSE: enter only after a 1-min close beyond the trigger
    confirm_within_min: int = 2        # CONFIRMED_CLOSE: give up if no close beyond within N closed minutes
                                       # FILTERED: FIRST_TOUCH entry plus the four filters below (user, 16 Oct)
    filter_min_touches: int = 3        # skip a level already touched this many times or more
    filter_min_range_pts: float = 300.0   # skip while the session range so far is narrower
    filter_max_itm_pts: float = 150.0     # skip strikes deeper in the money than this
    filter_max_overshoot_pts: float = 20.0  # skip if the index is already this far beyond the trigger


VARIANT_PREFIX = {"FIRST_TOUCH": "P", "CONFIRMED_CLOSE": "C", "FILTERED": "F"}


def scan_context(detail: dict) -> dict:
    """Facts from one scan for the FILTERED variant: futures vs its day open, session range, level touches."""
    fut = (detail or {}).get("futures") or {}
    ohlc = fut.get("ohlc") or {}
    bars = (detail or {}).get("idx1m") or []
    lv = (detail or {}).get("levels") or {}
    res, sup = lv.get("resistance"), lv.get("support")
    return {"futuresLtp": fut.get("ltp"), "futuresOpen": ohlc.get("open"),
            "sessionHigh": max(b["high"] for b in bars) if bars else None,
            "sessionLow": min(b["low"] for b in bars) if bars else None,
            "touches": {("CE", lv.get("breakoutAbove")): res["touches"] if res else None,
                        ("PE", lv.get("breakdownBelow")): sup["touches"] if sup else None}}


@dataclass
class _Arm:
    side: str
    trigger: float
    strikes: list
    fired: bool = False
    sids: dict = field(default_factory=dict)   # strike -> security id at arming (strikes may re-centre later)
    touches: int | None = None                  # touches of the level behind this trigger (FILTERED)


@dataclass
class _Trade:
    tid: str
    side: str
    strike: float
    security_id: str
    trigger: float
    entry_ms: int
    entry_ask: float
    entry_bid: float | None
    index_at_cross: float
    best: float = 0.0
    worst: float = 0.0
    ticks: int = 0
    gaps: int = 0
    last_bid: float | None = None
    path: list = field(default_factory=list)


class PaperTracker:
    def __init__(self, cfg: PaperConfig, log, in_skip_window):
        self.cfg, self.log, self.in_skip_window = cfg, log, in_skip_window
        self.arms: dict = {}             # (side, trigger) -> _Arm
        self.fired: set = set()          # (side, trigger) fired this session
        self.open: list = []
        self.closed: list = []
        self.last_index: float | None = None
        self.legs: dict = {}             # (strike, side) -> security id
        self.seq = 0
        self.pending: dict = {}          # CONFIRMED_CLOSE: key -> (arm, minute of the crossing)
        self.minute = None               # current minute (epoch ms // 60000) seen by the polls
        self.minute_last = None          # last index LTP polled inside that minute (~ its 1-min close)
        self.prefix = VARIANT_PREFIX[cfg.variant]
        self.ctx: dict = {}              # latest scan_context (FILTERED)

    # ------------------------------------------------------------ from scans
    def arm(self, rows, legs: dict, scan_ok: bool, ctx: dict | None = None):
        """Replace the armed triggers with the latest scan's OK rows."""
        self.legs = dict(legs)
        self.ctx = ctx or {}
        self.arms = {}
        if not scan_ok or not rows:
            return
        for r in rows:
            if r.status != "OK" or r.trigger is None:
                continue
            key = (r.side, float(r.trigger))
            if key in self.fired:
                continue
            touches = (self.ctx.get("touches") or {}).get((r.side, r.trigger))
            self.arms.setdefault(key, _Arm(r.side, float(r.trigger), [], touches=touches))
            if r.strike not in self.arms[key].strikes:
                self.arms[key].strikes.append(r.strike)
                self.arms[key].sids[r.strike] = self.legs.get((r.strike, r.side))

    def watch_ids(self) -> list:
        ids = {self.legs[k] for k in self.legs if self.legs[k]}
        ids |= {t.security_id for t in self.open}
        ids |= {sid for arm, _ in self.pending.values() for sid in arm.sids.values() if sid}
        return sorted(ids)

    # ------------------------------------------------------------- per poll
    def on_tick(self, now_ms: int, index_ltp, quotes: dict):
        """quotes: security_id -> (bid, ask). Returns nothing; logs events."""
        for t in list(self.open):
            self._update(t, now_ms, quotes.get(t.security_id))
        closed = self._roll_minute(now_ms, index_ltp)
        prev, self.last_index = self.last_index, index_ltp
        now = datetime.fromtimestamp(now_ms / 1000, timezone.utc)
        in_window = self.in_skip_window(now)
        if closed is not None and self.pending:
            self._confirm(closed, now_ms, index_ltp, quotes, in_window)
        if index_ltp is None or prev is None or in_window:
            return
        for key, arm in list(self.arms.items()):
            crossed = (prev < arm.trigger <= index_ltp) if arm.side == "CE" else (prev > arm.trigger >= index_ltp)
            if not crossed:
                continue
            self.fired.add(key)
            del self.arms[key]
            if self.cfg.variant == "CONFIRMED_CLOSE":
                self.pending[key] = (arm, now_ms // 60000)
                continue
            if self.cfg.variant == "FILTERED":
                self._enter_filtered(arm, now_ms, index_ltp, quotes)
                continue
            for strike in arm.strikes:
                self._enter(arm, strike, now_ms, index_ltp, quotes)

    def _enter_filtered(self, arm, now_ms, index_ltp, quotes):
        c, sgn = self.ctx, (1 if arm.side == "CE" else -1)
        fl, fo, hi, lo = c.get("futuresLtp"), c.get("futuresOpen"), c.get("sessionHigh"), c.get("sessionLow")
        trend = (fl - fo) * sgn if fl is not None and fo else None
        rng = hi - lo if hi is not None and lo is not None else None
        over = (index_ltp - arm.trigger) * sgn
        facts = {"futuresVsOpen": None if trend is None else round(trend * sgn, 2), "levelTouches": arm.touches,
                 "sessionRange": None if rng is None else round(rng, 2), "overshoot": round(over, 2)}
        fails = []
        if trend is None or trend <= 0:
            fails.append("against the day trend (futures vs open)" if trend is not None else "futures open unavailable")
        if arm.touches is None or arm.touches >= self.cfg.filter_min_touches:
            fails.append("level touched %s time(s)" % arm.touches)
        if rng is None or rng < self.cfg.filter_min_range_pts:
            fails.append("session range %s < %s" % (facts["sessionRange"], self.cfg.filter_min_range_pts))
        if over >= self.cfg.filter_max_overshoot_pts:
            fails.append("index already %.1f beyond the trigger" % over)
        if fails:
            self.log("info", "paper_skip", variant=self.cfg.variant, side=arm.side, trigger=arm.trigger,
                     reason="filters: " + "; ".join(fails), filterFacts=facts)
            return
        for strike in arm.strikes:
            itm = (index_ltp - strike) * sgn            # > 0: in the money by this many points
            if itm > self.cfg.filter_max_itm_pts:
                self.log("info", "paper_skip", variant=self.cfg.variant, side=arm.side, trigger=arm.trigger,
                         strike=strike, reason="strike %.0f pts in the money" % itm)
                continue
            self._enter(arm, strike, now_ms, index_ltp, quotes, filter_facts=facts)

    def _roll_minute(self, now_ms, index_ltp):
        """Returns (minute, close) of the minute that just ended, approximated by its last polled LTP."""
        m = now_ms // 60000
        out = None
        if self.minute is not None and m > self.minute and self.minute_last is not None:
            out = (self.minute, self.minute_last)
        if self.minute is None or m > self.minute:
            self.minute, self.minute_last = m, None
        if index_ltp is not None:
            self.minute_last = index_ltp
        return out

    def _confirm(self, closed, now_ms, index_ltp, quotes, in_window):
        minute, close = closed
        for key, (arm, since) in list(self.pending.items()):
            if minute < since:
                continue
            beyond = close > arm.trigger if arm.side == "CE" else close < arm.trigger
            if beyond and not in_window:
                del self.pending[key]
                for strike in arm.strikes:
                    self._enter(arm, strike, now_ms, index_ltp, quotes, confirm_close=close)
            elif minute - since + 1 >= self.cfg.confirm_within_min or in_window:
                del self.pending[key]
                self.log("info", "paper_skip", variant=self.cfg.variant, side=arm.side, trigger=arm.trigger,
                         reason="no 1-min close beyond the trigger within %d minute(s)" % self.cfg.confirm_within_min
                         if not in_window else "no-trade window began before confirmation")

    def _enter(self, arm, strike, now_ms, index_ltp, quotes, confirm_close=None, filter_facts=None):
        sid = arm.sids.get(strike) or self.legs.get((strike, arm.side))
        q = quotes.get(sid) if sid else None
        base = {"variant": self.cfg.variant, "side": arm.side, "strike": strike, "trigger": arm.trigger,
                "indexAtCross": index_ltp}
        if confirm_close is not None:
            base["confirmClose"] = confirm_close
        if filter_facts is not None:
            base["filterFacts"] = filter_facts
        if q is None or not q[1] or q[1] <= 0:
            self.log("info", "paper_skip", reason="no ask quote for the leg at the crossing", **base)
            return
        if len(self.open) >= self.cfg.max_open:
            self.log("warn", "paper_skip", reason="max_open reached", **base)
            return
        self.seq += 1
        bid, ask = q
        t = _Trade("%s%03d" % (self.prefix, self.seq), arm.side, strike, sid, arm.trigger, now_ms, ask, bid, index_ltp)
        self.open.append(t)
        self.log("info", "paper_entry", paperId=t.tid, entryAsk=ask, entryBid=bid,
                 spreadPts=round(ask - bid, 2) if bid else None,
                 spreadPct=round((ask - bid) / ((ask + bid) / 2) * 100, 3) if bid else None,
                 takeProfitAt=round(ask + self.cfg.take_profit_pts, 2), stopLossAt=round(ask - self.cfg.stop_loss_pts, 2),
                 note="PAPER (no order); exploratory trigger crossing, not a signal", **base)

    def _update(self, t, now_ms, q):
        held = (now_ms - t.entry_ms) / 1000
        bid = q[0] if q and q[0] and q[0] > 0 else None
        if bid is None:
            t.gaps += 1
        else:
            t.ticks += 1
            t.last_bid = bid
            pnl = bid - t.entry_ask
            t.best, t.worst = max(t.best, pnl), min(t.worst, pnl)
            t.path.append([round(held, 1), bid])
            if pnl >= self.cfg.take_profit_pts:
                return self._close(t, now_ms, "TAKE_PROFIT", bid)
            if pnl <= -self.cfg.stop_loss_pts:
                return self._close(t, now_ms, "STOP_LOSS", bid)
        if held >= self.cfg.time_stop_s:
            self._close(t, now_ms, "TIME_STOP", t.last_bid)

    def _close(self, t, now_ms, outcome, exit_bid):
        self.open.remove(t)
        pnl = None if exit_bid is None else round(exit_bid - t.entry_ask, 2)
        rec = {"paperId": t.tid, "variant": self.cfg.variant, "outcome": outcome, "side": t.side, "strike": t.strike, "trigger": t.trigger,
               "entryAsk": t.entry_ask, "exitBid": exit_bid, "pnlPts": pnl,
               "heldS": round((now_ms - t.entry_ms) / 1000, 1), "maxFavourablePts": round(t.best, 2),
               "maxAdversePts": round(t.worst, 2), "ticks": t.ticks, "quoteGaps": t.gaps, "path": t.path}
        if pnl is not None and self.cfg.lot_size:
            rec["pnlRsGross"] = round(pnl * self.cfg.lot_size, 2)
            if self.cfg.cost_per_trade_rs is not None:
                rec["pnlRsNet"] = round(pnl * self.cfg.lot_size - self.cfg.cost_per_trade_rs, 2)
        self.closed.append(rec)
        self.log("info", "paper_exit", note="PAPER (no order)", **rec)

    def close_all(self, now_ms: int, reason: str = "SESSION_END"):
        for t in list(self.open):
            self._close(t, now_ms, reason, t.last_bid)

    def summary(self) -> dict:
        out = {}
        for r in self.closed:
            out[r["outcome"]] = out.get(r["outcome"], 0) + 1
        decided = [r for r in self.closed if r["outcome"] in ("TAKE_PROFIT", "STOP_LOSS")]
        pnls = [r["pnlPts"] for r in self.closed if r["pnlPts"] is not None]
        return {"variant": self.cfg.variant, "trades": len(self.closed), "byOutcome": out,
                "winRateTpVsSl": round(sum(r["outcome"] == "TAKE_PROFIT" for r in decided) / len(decided), 3) if decided else None,
                "breakEvenWinRate": round(self.cfg.stop_loss_pts / (self.cfg.stop_loss_pts + self.cfg.take_profit_pts), 3),
                "totalPnlPts": round(sum(pnls), 2) if pnls else 0.0,
                "note": "PAPER results; entry at ask, exit at bid; no orders were placed"}
